    47→                $students = DB::table('students')
    48→                    ->join('users', 'users.id', '=', 'students.user_id')
    49→                    ->whereIn('students.id', $studentIds)
    50→                    ->where('students.status', 'aktif')
    51→                    ->orderBy('students.name')
