    58→                    ]);
    59→            }
    60→
    61→            // Fallback 1: students enrolled in the same package as this schedule
    62→            if ($students->isEmpty() && $schedule->paket_id) {
    63→                $students = DB::table('students')
    64→                    ->join('users', 'users.id', '=', 'students.user_id')
    65→                    ->where('students.package_id', $schedule->paket_id)
