   121→    public function store(Request $request)
   122→    {
   123→        $schedule = Schedule::findOrFail($request->input('jadwal_id'));
   124→
   125→        // Attendance only allowed during class hours
   126→        $now = now();
   127→        $classDate = \Carbon\Carbon::parse($schedule->tanggal)->format('Y-m-d');
   128→        $startTime = \Carbon\Carbon::parse($classDate . ' ' . $schedule->jam_mulai);
   129→        $endTime   = \Carbon\Carbon::parse($classDate . ' ' . $schedule->jam_selesai);
   130→
   131→        if ($now->lt($startTime)) {
   132→            return response()->json(['success' => false, 'message' => 'Absensi hanya bisa dilakukan saat kelas sudah dimulai (' . $startTime->format('H:i') . ' WIB).'], 422);
   133→        }
   134→        if ($now->gt($endTime)) {
   135→            return response()->json(['success' => false, 'message' => 'Absensi sudah ditutup. Kelas telah selesai pada ' . $endTime->format('H:i') . ' WIB.'], 422);
   136→        }
   137→
   138→        $data = $request->validate([
   139→            'jadwal_id'       => 'required|exists:schedules,id',
   140→            'hadir_ids'       => 'nullable|array',
   141→            'hadir_ids.*'     => 'integer',
   142→        ]);
   143→
   144→        $hadirIds = array_map('intval', $data['hadir_ids'] ?? []);
   145→
   146→        // Collect all student IDs currently shown (from class_students + fallbacks)
   147→        $studentIds = DB::table('class_students')
   148→            ->where('class_id', $schedule->kelas_id)
   149→            ->pluck('student_id')
   150→            ->toArray();
   151→
   152→        // Fallback 1: students enrolled in the same package
   153→        if (empty($studentIds) && $schedule->paket_id) {
   154→            $studentIds = DB::table('students')
   155→                ->where('package_id', $schedule->paket_id)
   156→                ->where('status', 'aktif')
   157→                ->pluck('id')
   158→                ->toArray();
   159→        }
   160→
   161→        // Fallback 2: all students in branch if class_students and package both empty
   162→        if (empty($studentIds) && $schedule->kelas_id) {
   163→            $class = SchoolClass::find($schedule->kelas_id);
   164→            if ($class && $class->cabang_id) {
   165→                $studentIds = DB::table('students')
   166→                    ->where('branch_id', $class->cabang_id)
   167→                    ->where('status', 'aktif')
   168→                    ->pluck('id')
   169→                    ->toArray();
   170→            }
   171→        }
   172→
   173→        // Merge hadir_ids into studentIds to include user proxies
   174→        $allIds = array_unique(array_merge($studentIds, $hadirIds));
   175→
   176→        if (empty($allIds)) {
   177→            return response()->json(['success' => false, 'message' => 'Belum ada siswa di kelas ini.'], 422);
   178→        }
   179→
   180→        $now = now();
   181→
   182→        foreach ($allIds as $siswaId) {
   183→            $guruHadir = in_array($siswaId, $hadirIds);
   184→
   185→            $existing = DB::table('absensi_siswas')
   186→                ->where('jadwal_id', $schedule->id)
   187→                ->where('siswa_id', $siswaId)
   188→                ->first();
   189→
   190→            if ($existing) {
   191→                // Preserve siswa_konfirmasi_at, only update guru_hadir
   192→                DB::table('absensi_siswas')
   193→                    ->where('jadwal_id', $schedule->id)
   194→                    ->where('siswa_id', $siswaId)
   195→                    ->update([
   196→                        'guru_hadir'  => $guruHadir,
   197→                        'status'      => $this->computeStatus($guruHadir, $existing->siswa_konfirmasi_at),
   198→                        'updated_at'  => $now,
   199→                    ]);
   200→            } else {
   201→                DB::table('absensi_siswas')->insert([
   202→                    'jadwal_id'           => $schedule->id,
   203→                    'siswa_id'            => $siswaId,
   204→                    'guru_hadir'          => $guruHadir,
   205→                    'siswa_konfirmasi_at' => null,
   206→                    'status'              => $guruHadir ? 'menunggu_konfirmasi' : 'tidak_hadir',
   207→                    'catatan'             => null,
   208→                    'created_at'          => $now,
   209→                    'updated_at'          => $now,
   210→                ]);
   211→            }
   212→        }
   213→
   214→        return response()->json(['success' => true, 'message' => 'Absensi berhasil disimpan!']);
   215→    }
   216→
   217→    private function computeStatus(bool $guruHadir, $siswaKonfirmasiAt): string
   218→    {
   219→        return \App\Models\AbsensiSiswa::computeStatus($guruHadir, $siswaKonfirmasiAt);
   220→    }
