   653→        <div class="col-md-6">
   654→            <div class="p-3 rounded-3 d-flex align-items-start gap-3" style="background:var(--soft-info-bg,#eff6ff);border:1.5px solid #3b82f6">
   655→                <div style="font-size:22px;line-height:1">💻</div>
   656→                <div>
   657→                    <div class="fw-semibold" style="font-size:13px;color:#1d4ed8">Kelas Online</div>
   658→                    <div style="font-size:12px;color:var(--text-muted)">Tidak ada pengecekan ruang fisik untuk kelas online.</div>
   659→                </div>
   660→            </div>
   661→        </div>`;
   662→    } else {
   663→        html += `
   664→        <div class="col-md-6">
   665→            <div class="p-3 rounded-3 d-flex align-items-start gap-3" style="background:#fffbeb;border:1.5px solid #f59e0b">
   666→                <div style="font-size:22px;line-height:1">🏠</div>
   667→                <div>
   668→                    <div class="fw-semibold" style="font-size:13px;color:#92400e">Home Visit</div>
   669→                    <div style="font-size:12px;color:var(--text-muted)">Kunjungan ke alamat siswa — tidak ada pengecekan ruang.</div>
   670→                </div>
   671→            </div>
   672→        </div>`;
   673→    }
   674→
   675→    // Teacher availability summary
   676→    const busyCount  = busyTeacherIds.length;
   677→    const totalCount = teachers.length;
   678→    const freeCount  = totalCount - busyCount;
   679→    html += `
   680→    <div class="col-md-6">
   681→        <div class="p-3 rounded-3 d-flex align-items-start gap-3" style="background:${freeCount > 0 ? 'var(--soft-success-bg,#d1fae5)' : '#fef2f2'};border:1.5px solid ${freeCount > 0 ? '#10b981' : '#ef4444'}">
   682→            <div style="font-size:22px;line-height:1">${freeCount > 0 ? '👨‍🏫' : '⚠️'}</div>
   683→            <div>
   684→                <div class="fw-semibold" style="font-size:13px;color:${freeCount > 0 ? '#047857' : '#b91c1c'}">
