   727→// ─── STEP 4: Guru & Honor ────────────────────────────────────────────────
   728→
   729→function renderGuruList() {
   730→    if (!currentPaket) return;
   731→    const mapelId = currentMapelId ? parseInt(currentMapelId) : null;
   732→
   733→    // Determine preferred teachers (from package-course-teacher assignments)
   734→    let pkgTeacherIds = [];
   735→    if (mapelId && currentPaket.course_teachers) {
   736→        const ct = currentPaket.course_teachers[mapelId];
   737→        if (ct && ct.length > 0) pkgTeacherIds = ct.map(Number);
   738→    }
   739→
   740→    // Categorize: preferred + available / preferred + busy / other available / other busy
   741→    let preferred = [], others = [];
   742→    teachers.forEach(t => {
   743→        const isPref = pkgTeacherIds.length > 0
   744→            ? pkgTeacherIds.includes(t.id)
   745→            : (mapelId ? t.course_ids.includes(mapelId) : false);
   746→        if (isPref) preferred.push(t); else others.push(t);
   747→    });
   748→
   749→    let html = '';
   750→    if (preferred.length > 0) {
   751→        html += `<div class="col-12 mb-1"><div class="text-muted fw-semibold" style="font-size:11px;text-transform:uppercase;letter-spacing:.5px">✅ Guru sesuai mata pelajaran (${preferred.length})</div></div>`;
   752→        preferred.forEach(t => { html += renderGuruCard(t, true); });
   753→    }
   754→    if (others.length > 0) {
   755→        html += `<div class="col-12 mt-2 mb-1"><div class="text-muted fw-semibold" style="font-size:11px;text-transform:uppercase;letter-spacing:.5px">— Guru lainnya (${others.length})</div></div>`;
   756→        others.forEach(t => { html += renderGuruCard(t, false); });
   757→    }
   758→    if (!html) html = '<div class="col-12 text-muted" style="font-size:13px">Belum ada guru aktif.</div>';
   759→
   760→    document.getElementById('guruList').innerHTML = html;
   761→    document.getElementById('guruNote').textContent = pkgTeacherIds.length > 0
   762→        ? `${preferred.length} guru ditugaskan untuk mapel ini dalam paket — tampil di atas.`
   763→        : (preferred.length > 0 ? `${preferred.length} guru terdaftar mengajar mapel ini.` : 'Belum ada guru yang ditetapkan untuk mapel ini.');
   764→
   765→    // Re-select if previously chosen
   766→    if (selectedGuruId) selectGuru(selectedGuruId);
   767→}
   768→
   769→function renderGuruCard(t, isPreferred) {
   770→    const isBusy = busyTeacherIds.includes(t.id);
   771→    const badgeBg    = isBusy ? '#fef2f2'    : (isPreferred ? 'var(--soft-success-bg,#d1fae5)' : 'var(--input-bg)');
   772→    const badgeBorder= isBusy ? '#ef4444'    : (isPreferred ? '#10b981' : 'var(--card-border)');
   773→    const statusBadge= isBusy
   774→        ? `<span style="background:#fee2e2;color:#b91c1c;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:600">⚠️ Konflik Jadwal</span>`
   775→        : `<span style="background:#d1fae5;color:#047857;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:600">✅ Tersedia</span>`;
   776→
   777→    return `
   778→    <div class="col-md-4 col-sm-6">
   779→        <div class="guru-card p-3 rounded-3" data-id="${t.id}" data-name="${t.name}"
   780→             style="border:2px solid ${badgeBorder};background:${badgeBg};cursor:${isBusy ? 'not-allowed' : 'pointer'};transition:.2s;opacity:${isBusy ? '.6' : '1'}"
   781→             ${isBusy ? '' : `onclick="selectGuru(${t.id})"`}>
   782→            <div class="d-flex align-items-center gap-2 mb-2">
   783→                <div style="width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,#461256,#c84ddf);display:flex;align-items:center;justify-content:center;color:white;font-size:13px;font-weight:700;flex-shrink:0">
   784→                    ${t.name.charAt(0).toUpperCase()}
   785→                </div>
   786→                <div>
   787→                    <div class="fw-semibold" style="font-size:13px;line-height:1.3">${t.name}</div>
   788→                    ${t.branch ? `<div class="text-muted" style="font-size:10px">${t.branch}</div>` : ''}
   789→                </div>
   790→            </div>
   791→            <div class="d-flex align-items-center justify-content-between">
   792→                ${statusBadge}
   793→                ${t.nig ? `<span class="text-muted" style="font-size:10px">NIG: ${t.nig}</span>` : ''}
   794→            </div>
   795→        </div>
   796→    </div>`;
   797→}
