   799→function selectGuru(guruId) {
   800→    selectedGuruId = guruId;
   801→    document.getElementById('guru_id').value = guruId;
   802→
   803→    document.querySelectorAll('.guru-card').forEach(card => {
   804→        const isSelected = parseInt(card.dataset.id) === guruId;
   805→        const isBusy     = busyTeacherIds.includes(parseInt(card.dataset.id));
   806→        if (!isBusy) {
   807→            card.style.border = isSelected ? '2px solid #c84ddf' : '2px solid var(--card-border)';
   808→            card.style.boxShadow = isSelected ? '0 0 0 3px rgba(200,77,223,.15)' : '';
   809→        }
   810→    });
   811→
   812→    const t = teachers.find(x => x.id == guruId);
   813→    if (t) {
   814→        const honorInfo = document.getElementById('honorInfo');
   815→        honorInfo.innerHTML = `<i class="bi bi-person-check me-1 text-success"></i><strong>${t.name}</strong> dipilih sebagai guru pengajar. Masukkan honor per sesi jika ada kesepakatan.`;
   816→    }
   817→
   818→    document.getElementById('submitBtn').disabled = false;
   819→}
