   839→    fetch(`${packageStudentsBaseUrl}/${paketId}/students`, {
   840→        headers: { 'Accept': 'application/json', 'X-CSRF-TOKEN': csrf }
   841→    })
   842→    .then(r => { if (!r.ok) throw new Error(); return r.json(); })
   843→    .then(data => {
   844→        const students = data.students || [];
   845→        counter.textContent = students.length + ' siswa';
   846→        content.innerHTML = students.length
   847→            ? students.map(s => `<span style="background:var(--soft-primary);color:#461256;padding:4px 10px;border-radius:20px;font-size:12px;font-weight:500;display:inline-flex;align-items:center;gap:4px"><i class="bi bi-person-fill"></i>${s.name}${s.nis ? `<span style="opacity:.65;font-size:10px">#${s.nis}</span>` : ''}</span>`).join('')
   848→            : '<span class="text-muted" style="font-size:12px"><i class="bi bi-info-circle me-1"></i>Belum ada siswa terdaftar di paket ini.</span>';
   849→    })
   850→    .catch(() => {
   851→        content.innerHTML = '<span class="text-muted" style="font-size:12px"><i class="bi bi-exclamation-circle me-1"></i>Gagal memuat daftar siswa.</span>';
   852→    });
   853→}
